import torch
from liger_kernel.ops.geglu import LigerGELUMulFunction


@torch.no_grad()
def run(x):
    # x shape: (batch, seq_len, 2*intermediate_size)
    # Split into gate and up halves
    half = x.shape[-1] // 2
    a, b = x[..., :half], x[..., half:]
    return LigerGELUMulFunction.apply(a, b)
